package com.klondike.game

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class GameTest {

    private fun dealt(seed: Long = 42L) = Game().apply { deal(seed) }

    @Test fun deal_lays_out_klondike() {
        val g = dealt()
        for (i in 0..6) {
            assertEquals("column $i size", i + 1, g.tableau[i].size)
            g.tableau[i].forEachIndexed { idx, c ->
                assertEquals("faceUp in col $i at $idx", idx == i, c.faceUp)
            }
        }
        assertEquals(24, g.stock.size)
        assertEquals(0, g.waste.size)
        assertEquals(0, g.foundations.sumOf { it.size })
        val all = g.tableau.flatMap { it } + g.stock + g.waste
        assertEquals(52, all.size)
        assertEquals("no duplicate cards", 52, all.map { it.rank to it.suit }.toSet().size)
        g.stock.forEach { assertFalse(it.faceUp) }
    }

    @Test fun deal_is_deterministic_by_seed() {
        val a = dealt(7L).tableau.map { col -> col.map { it.rank to it.suit } }
        val b = dealt(7L).tableau.map { col -> col.map { it.rank to it.suit } }
        val c = dealt(8L).tableau.map { col -> col.map { it.rank to it.suit } }
        assertEquals(a, b)
        assertNotEquals(a, c)
    }

    @Test fun draw_moves_stock_to_waste_face_up() {
        val g = dealt()
        val before = g.stock.size
        assertTrue(g.drawFromStock())
        assertEquals(before - 1, g.stock.size)
        assertEquals(1, g.waste.size)
        assertTrue(g.waste.last().faceUp)
    }

    @Test fun draw_recycles_when_stock_empty() {
        val g = dealt()
        repeat(24) { assertTrue(g.drawFromStock()) }
        assertEquals(0, g.stock.size)
        assertEquals(24, g.waste.size)
        assertTrue(g.drawFromStock())          // recycle
        assertEquals(24, g.stock.size)
        assertEquals(0, g.waste.size)
        g.stock.forEach { assertFalse(it.faceUp) }
    }

    @Test fun foundation_takes_ace_then_same_suit_ascending() {
        val g = Game().apply { deal(1L) }
        // drive the piles directly -- rules, not layout
        g.waste.addLast(Card(1, 2).apply { faceUp = true })     // A♣
        assertTrue(g.moveWasteToFoundation())
        val f = g.foundations.indexOfFirst { it.size == 1 }
        assertTrue(f >= 0)

        g.waste.addLast(Card(3, 2).apply { faceUp = true })     // 3♣ - skips 2♣
        assertFalse(g.moveWasteToFoundation())
        g.waste.addLast(Card(2, 2).apply { faceUp = true })     // 2♣ - ok
        assertTrue(g.moveWasteToFoundation())
        assertEquals(2, g.foundations[f].size)

        g.waste.addLast(Card(3, 3).apply { faceUp = true })     // 3♠ wrong suit
        assertFalse(g.moveWasteToFoundation())
    }

    @Test fun empty_column_takes_only_a_king() {
        val g = Game().apply { deal(2L) }
        g.tableau[3].clear()
        g.waste.addLast(Card(7, 0).apply { faceUp = true })
        assertFalse(g.moveWasteToTableau(3))
        g.waste.addLast(Card(13, 0).apply { faceUp = true })
        assertTrue(g.moveWasteToTableau(3))
        assertEquals(13, g.tableau[3].last().rank)
    }

    @Test fun tableau_builds_down_alternating_colour() {
        val g = Game().apply { deal(3L) }
        g.tableau[0].clear()
        g.tableau[0].addLast(Card(8, 3).apply { faceUp = true })   // 8♠ black
        g.waste.addLast(Card(7, 3).apply { faceUp = true })        // 7♠ same colour -> no
        assertFalse(g.moveWasteToTableau(0))
        g.waste.addLast(Card(7, 0).apply { faceUp = true })        // 7♥ red, one lower -> yes
        assertTrue(g.moveWasteToTableau(0))
    }

    @Test fun moving_a_tableau_card_flips_the_one_underneath() {
        val g = Game().apply { deal(4L) }
        g.tableau[2].clear()
        g.tableau[2].addLast(Card(5, 3))                            // face down
        g.tableau[2].addLast(Card(1, 1).apply { faceUp = true })    // A♦ on top
        assertTrue(g.moveTableauToFoundation(2))
        assertEquals(1, g.tableau[2].size)
        assertTrue("exposed card flips", g.tableau[2].last().faceUp)
    }

    @Test fun move_run_between_columns() {
        val g = Game().apply { deal(5L) }
        g.tableau[1].clear(); g.tableau[4].clear()
        g.tableau[1].addLast(Card(9, 3).apply { faceUp = true })    // 9♠
        g.tableau[1].addLast(Card(8, 0).apply { faceUp = true })    // 8♥
        g.tableau[1].addLast(Card(7, 3).apply { faceUp = true })    // 7♠  -> valid run 9♠8♥7♠
        g.tableau[4].addLast(Card(10, 0).apply { faceUp = true })   // 10♥
        assertTrue(g.moveTableauRun(1, 0, 4))
        assertEquals(0, g.tableau[1].size)
        assertEquals(4, g.tableau[4].size)
        assertEquals(listOf(10, 9, 8, 7), g.tableau[4].map { it.rank })
    }

    @Test fun won_when_all_foundations_full() {
        val g = Game().apply { deal(6L) }
        assertFalse(g.isWon())
        for (s in 0..3) for (r in 1..13) g.foundations[s].addLast(Card(r, s))
        assertTrue(g.isWon())
    }

    @Test fun moves_counter_advances_on_a_real_move_only() {
        val g = dealt()
        val m0 = g.moves
        g.moveWasteToFoundation()               // nothing to move
        assertEquals(m0, g.moves)
        g.drawFromStock()
        assertEquals(m0 + 1, g.moves)
    }
}

